void linear1_normal(
    int X[PAD_M_LINEAR1][PACK_OF_N_LINEAR1],
    int W[PAD_N_LINEAR1][PACK_OF_K_LINEAR1],
    int B[PAD_K_LINEAR1],
    int M, int N, int ReLU_en,
    int Y[PAD_M_LINEAR1][PACK_OF_K_LINEAR1]
) {
    for (int i = 0; i < PAD_M_LINEAR1; i++) {
        int32_t acc[PAD_K_LINEAR1];
        for (int k = 0; k < PAD_K_LINEAR1; k++) {
			acc[k] = B[k];
		}

        for (int k = 0; k < PAD_N_LINEAR1; k++) {
            int packed_a = X[i][k / DIN_PER_PACK];
            int shift_a = (3 - (k % DIN_PER_PACK)) * 8;
            int8_t a_val = (int8_t)((packed_a >> shift_a) & 0xFF);

            for (int j_pack = 0; j_pack < PACK_OF_K_LINEAR1; j_pack++) {
                int packed_w = W[k][j_pack];

                int8_t w0 = (int8_t)((packed_w >> 24) & 0xFF);
                int8_t w1 = (int8_t)((packed_w >> 16) & 0xFF);
                int8_t w2 = (int8_t)((packed_w >> 8)  & 0xFF);
                int8_t w3 = (int8_t)((packed_w >> 0)  & 0xFF);

                int j_base = j_pack * DIN_PER_PACK;
                acc[j_base + 0] += (int32_t)a_val * w0;
                acc[j_base + 1] += (int32_t)a_val * w1;
                acc[j_base + 2] += (int32_t)a_val * w2;
                acc[j_base + 3] += (int32_t)a_val * w3;
            }
        }

        for (int j_pack = 0; j_pack < PACK_OF_K_LINEAR1; j_pack++) {
            int32_t packed_y = 0;

            for (int byte_idx = 0; byte_idx < DIN_PER_PACK; byte_idx++) {
                int j = j_pack * DIN_PER_PACK + byte_idx;
                int32_t q_val = 0;

				int64_t temp = (int64_t)acc[j] * M;
				q_val = (int32_t)(temp >> N);

				if (ReLU_en && q_val < 0) {
					q_val = 0;
				}

                if (q_val > 127) q_val = 127;
                if (q_val < -128) q_val = -128;

                uint8_t out_8 = (uint8_t)(q_val & 0xFF);

                int shift_y = (3 - byte_idx) * 8;
                packed_y |= ((uint32_t)out_8 << shift_y);
            }

            Y[i][j_pack] = packed_y;
        }
    }

#ifdef _DEBUG_INFO_
    for (int m = 0; m < M_LINEAR1; m++) {
        for (int k = 0; k < K_LINEAR1; k++) {
            int packed_y = Y[m][k / DIN_PER_PACK];
            int shift = (3 - (k % DIN_PER_PACK)) * 8;
            int8_t val = (int8_t)((packed_y >> shift) & 0xFF);
            printf("%d\t", val);
        }
        printf("\r\n");
    }
#endif
}

