void clear_variables(
		int Y_1[PAD_M_LINEAR1][PACK_OF_K_LINEAR1],
		int Y_2[PAD_M_LINEAR2][PACK_OF_K_LINEAR2],
		int Y_3[PAD_M_LINEAR3][PACK_OF_K_LINEAR3],
		int Y_4[PAD_M_LINEAR4][PACK_OF_K_LINEAR4],
		int result[PAD_M_LINEAR5][PACK_OF_K_LINEAR5]
) {
	for (int m=0; m<PAD_M_LINEAR1; m++) {
		for (int k=0; k<PACK_OF_K_LINEAR1; k++) {
			Y_1[m][k] = 0;
		}
	}
	for (int m=0; m<PAD_M_LINEAR2; m++) {
		for (int k=0; k<PACK_OF_K_LINEAR2; k++) {
			Y_2[m][k] = 0;
		}
	}
	for (int m=0; m<PAD_M_LINEAR3; m++) {
		for (int k=0; k<PACK_OF_K_LINEAR3; k++) {
			Y_3[m][k] = 0;
		}
	}
	for (int m=0; m<PAD_M_LINEAR4; m++) {
		for (int k=0; k<PACK_OF_K_LINEAR4; k++) {
			Y_4[m][k] = 0;
		}
	}
	for (int m=0; m<PAD_M_LINEAR5; m++) {
		for (int k=0; k<PACK_OF_K_LINEAR5; k++) {
			result[m][k] = 0;
		}
	}
};


void init_padding_arrays() {
	for (int n = 0; n < N_LINEAR1; n++) {
		for (int pack_k = 0; pack_k < RAW_PACK_OF_K_LINEAR1; pack_k++) {
			W_1_pad[n][pack_k] = W_1[n][pack_k];
		}
	}
	for (int k = 0; k < K_LINEAR1; k++) {
		B_1_pad[k] = B_1[k];
	}

	for (int n = 0; n < N_LINEAR2; n++) {
		for (int pack_k = 0; pack_k < RAW_PACK_OF_K_LINEAR2; pack_k++) {
			W_2_pad[n][pack_k] = W_2[n][pack_k];
		}
	}
	for (int k = 0; k < K_LINEAR2; k++) {
		B_2_pad[k] = B_2[k];
	}

	for (int n = 0; n < N_LINEAR3; n++) {
		for (int pack_k = 0; pack_k < RAW_PACK_OF_K_LINEAR3; pack_k++) {
			W_3_pad[n][pack_k] = W_3[n][pack_k];
		}
	}
	for (int k = 0; k < K_LINEAR3; k++) {
		B_3_pad[k] = B_3[k];
	}

	for (int n = 0; n < N_LINEAR4; n++) {
		for (int pack_k = 0; pack_k < RAW_PACK_OF_K_LINEAR4; pack_k++) {
			W_4_pad[n][pack_k] = W_4[n][pack_k];
		}
	}
	for (int k = 0; k < K_LINEAR4; k++) {
		B_4_pad[k] = B_4[k];
	}

	for (int n = 0; n < N_LINEAR5; n++) {
		for (int pack_k = 0; pack_k < RAW_PACK_OF_K_LINEAR5; pack_k++) {
			W_5_pad[n][pack_k] = W_5[n][pack_k];
		}
	}
	for (int k = 0; k < K_LINEAR5; k++) {
		B_5_pad[k] = B_5[k];
	}
}


