static inline uint64_t get_cycle() {
    uint64_t cycle;
    // 读取 cycle 寄存器
    __asm__ __volatile__("rdcycle %0" : "=r"(cycle));
    return cycle;
}

static inline uint64_t get_instret() {
    uint64_t instret;
    // 读取 instret (Instruction Retired) 寄存器
    __asm__ __volatile__("rdinstret %0" : "=r"(instret));
    return instret;
}

